            )

        params = params or {}
        protocol_version = params.get("protocolVersion", DEFAULT_PROTOCOL_VERSION)
        result = {
            "protocolVersion": protocol_version,
            "serverInfo": {"name": "workshop-mcp-server", "version": "0.1.0"},
